// Generated by GitHub Copilot - Nov-17-2026
// ResumeLens front-end. Security: all dynamic text is inserted with textContent (never innerHTML)
// so resume / job content cannot inject markup. Accessibility: ARIA tabs with arrow-key support,
// live regions for status, focus management after long-running actions.
import { LANG_NAMES, STRINGS } from "./i18n.js";

const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => [...document.querySelectorAll(sel)];
const TONES = ["formal", "conversational", "enthusiastic"];
const RING_LEN = 326.73;

const state = {
  ui: "en",
  fileMeta: null,
  analysis: null,
  originalScore: null,
  optimized: "",
  letters: null,
  templates: [],
  accents: {},
  accent: "",
  template: "classic",
  ai: { available: false },
};

/** Translate a key with {placeholder} substitution; falls back to English, then the key. */
function t(key, params = {}) {
  const raw = STRINGS[state.ui]?.[key] ?? STRINGS.en[key] ?? key;
  return raw.replace(/\{(\w+)\}/g, (_, k) => (params[k] ?? ""));
}

/** Create an element with attributes and text/children (text is always set via textContent). */
function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === "class") node.className = v;
    else if (k === "text") node.textContent = v;
    else node.setAttribute(k, v);
  }
  for (const child of children) if (child) node.append(child);
  return node;
}

// ------------------------------------------------------------------ i18n + theme
function applyLanguage(lang) {
  state.ui = STRINGS[lang] ? lang : "en";
  document.documentElement.lang = state.ui;
  document.documentElement.dir = state.ui === "ar" ? "rtl" : "ltr";
  $$("[data-i18n]").forEach((n) => { n.textContent = t(n.dataset.i18n); });
  $$("[data-i18n-placeholder]").forEach((n) => { n.placeholder = t(n.dataset.i18nPlaceholder); });
  $$("[data-i18n-aria]").forEach((n) => { n.setAttribute("aria-label", t(n.dataset.i18nAria)); });
  $$("[data-i18n-title]").forEach((n) => { n.title = t(n.dataset.i18nTitle); });
  $("#ui-lang").value = state.ui;
  localStorage.setItem("rl-ui-lang", state.ui);
  renderAIStatus();
  renderTemplates();
  renderAccents();
  if (state.analysis) renderAnalysis(state.analysis);
  if (state.lastOptimize) renderChanges(state.lastOptimize);
  if (state.letters) renderLetterEngine();
}

function applyTheme(theme) {
  document.documentElement.dataset.theme = theme;
  $("#theme-toggle").setAttribute("aria-pressed", String(theme === "dark"));
  localStorage.setItem("rl-theme", theme);
}

// ------------------------------------------------------------------ feedback helpers
let toastTimer;
function toast(msg) {
  const box = $("#toast");
  box.textContent = msg;
  box.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => box.classList.remove("show"), 3200);
}

function showError(msg) {
  const box = $("#input-error");
  box.textContent = msg;
  box.hidden = !msg;
}

async function withBusy(label, fn) {
  const overlay = $("#busy");
  const active = document.activeElement;
  $("#busy-text").textContent = label;
  overlay.hidden = false;
  try {
    return await fn();
  } finally {
    overlay.hidden = true;
    if (active && document.contains(active)) active.focus();
  }
}

/** JSON API call that turns server error codes into translated messages. */
async function api(path, body, { raw = false } = {}) {
  let res;
  try {
    res = await fetch(path, body === undefined ? {} : {
      method: "POST",
      headers: body instanceof FormData ? {} : { "Content-Type": "application/json" },
      body: body instanceof FormData ? body : JSON.stringify(body),
    });
  } catch {
    throw new Error(t("err_network"));
  }
  if (!res.ok) {
    let code = "err_server";
    try {
      const data = await res.json();
      if (typeof data.detail === "string") code = data.detail;
    } catch { /* non-JSON error body */ }
    throw new Error(STRINGS.en[code] ? t(code) : t("err_server"));
  }
  return raw ? res : res.json();
}

// ------------------------------------------------------------------ AI status
/** On a hosted instance the "never leaves this computer" promise is not true - switch to honest wording. */
function applyHostedMode() {
  const swaps = { privacy_note: "privacy_note_hosted", footer: "footer_hosted", hero_sub: "hero_sub_hosted" };
  $$("[data-i18n]").forEach((n) => {
    const hosted = swaps[n.dataset.i18n];
    if (hosted) {
      n.dataset.i18n = hosted;
      n.textContent = t(hosted);
    }
  });
}

async function refreshAI() {
  try {
    const data = await api("/api/health");
    state.ai = data.ai;
    if (data.mode === "hosted") applyHostedMode();
  } catch {
    state.ai = { available: false };
  }
  renderAIStatus();
}

function renderAIStatus() {
  const badge = $("#ai-status");
  if (state.ai.available === undefined) return;
  badge.className = `badge ${state.ai.available ? "badge-ok" : "badge-warn"}`;
  badge.textContent = state.ai.available ? t("ai_on", { model: state.ai.model }) : t("ai_off");
}

// ------------------------------------------------------------------ input handling
async function handleFile(file) {
  if (!file) return;
  showError("");
  if (file.size > 5 * 1024 * 1024) { showError(t("err_too_large")); return; }
  const form = new FormData();
  form.append("file", file);
  try {
    const data = await withBusy(t("reading_file"), () => api("/api/extract", form));
    $("#resume-text").value = data.text;
    state.fileMeta = data.meta;
    $("#file-name").textContent = t("file_loaded", { name: file.name });
    toast(t("file_loaded", { name: file.name }));
  } catch (err) {
    showError(err.message);
  }
}

function setupDropZone() {
  const zone = $("#drop-zone");
  ["dragenter", "dragover"].forEach((ev) => zone.addEventListener(ev, (e) => {
    e.preventDefault();
    zone.classList.add("dragging");
  }));
  ["dragleave", "drop"].forEach((ev) => zone.addEventListener(ev, (e) => {
    e.preventDefault();
    zone.classList.remove("dragging");
  }));
  zone.addEventListener("drop", (e) => handleFile(e.dataTransfer?.files?.[0]));
}

// ------------------------------------------------------------------ analysis
async function runAnalysis() {
  const resume = $("#resume-text").value.trim();
  showError("");
  if (resume.length < 30) { showError(t("need_resume")); $("#resume-text").focus(); return; }
  try {
    const data = await withBusy(t("analyzing"), () => api("/api/analyze", {
      resume_text: resume, job_description: $("#jd-text").value.trim(), file_meta: state.fileMeta,
    }));
    state.analysis = data;
    state.originalScore = data.score;
    state.optimized = "";
    state.lastOptimize = null;
    state.letters = null;
    $("#opt-result").hidden = true;
    $("#opt-engine").hidden = true;
    $("#opt-score").hidden = true;
    $("#cl-result").hidden = true;
    $("#cl-engine").hidden = true;
    $("#workspace").hidden = false;
    renderAnalysis(data);
    selectTab("analysis", true);
    $("#workspace").scrollIntoView({ behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth" });
  } catch (err) {
    showError(err.message);
  }
}

function scoreLabel(score) {
  if (score >= 85) return ["score_excellent", "var(--ok)"];
  if (score >= 70) return ["score_good", "var(--accent)"];
  if (score >= 50) return ["score_fair", "var(--warn)"];
  return ["score_poor", "var(--bad)"];
}

function renderAnalysis(a) {
  const [labelKey, color] = scoreLabel(a.score);
  $("#score-num").textContent = a.score;
  $("#score-label").textContent = t(labelKey);
  $("#score-ring").setAttribute("role", "img");
  $("#score-ring").setAttribute("aria-label", `${t("score_title")}: ${a.score}/100 – ${t(labelKey)}`);
  const ring = $("#ring-fg");
  ring.style.setProperty("--ring-color", color);
  requestAnimationFrame(() => { ring.style.strokeDashoffset = String(RING_LEN * (1 - a.score / 100)); });
  $("#score-stats").textContent = t("stats_line", a.stats);

  const bd = $("#breakdown");
  bd.replaceChildren(...a.breakdown.map((b) => {
    const pct = Math.round((b.score / b.max) * 100);
    const fill = el("span");
    fill.style.background = pct >= 75 ? "var(--ok)" : pct >= 45 ? "var(--accent)" : "var(--bad)";
    requestAnimationFrame(() => { fill.style.width = `${pct}%`; });
    return el("li", {},
      el("div", { class: "breakdown-row" }, el("span", { text: t(`bd_${b.key}`) }), el("strong", { text: `${b.score}/${b.max}` })),
      el("div", { class: "bar", role: "presentation" }, fill));
  }));

  const kw = a.keywords;
  const kwBox = $("#kw-content");
  if (!a.has_job_description) {
    $("#kw-summary").textContent = t("no_jd_hint");
    kwBox.replaceChildren();
  } else {
    $("#kw-summary").textContent = t("kw_match", { percent: kw.match_percent });
    const chips = (items, cls) => items.length
      ? el("ul", { class: "chips" }, ...items.map((k) => el("li", { class: `chip ${cls}`, text: k })))
      : el("p", { class: "muted small", text: t("kw_none") });
    kwBox.replaceChildren(
      el("p", { class: "chips-label", text: t("kw_matched") }), chips(kw.matched, "chip-ok"),
      el("p", { class: "chips-label", text: t("kw_missing") }), chips(kw.missing, "chip-bad"));
  }

  const risks = $("#risks");
  risks.replaceChildren(...(a.risks.length ? a.risks.map((r) => {
    const params = { ...r.params };
    if (params.section) params.section = t(`sec_${params.section}`);
    return el("li", { class: "risk" },
      el("span", { class: `sev sev-${r.severity}`, text: t(`sev_${r.severity}`) }),
      el("span", { text: t(r.code, params) }));
  }) : [el("li", { class: "empty-ok", text: t("no_risks") })]));

  const weak = $("#weak-points");
  weak.replaceChildren(...(a.weak_points.length ? a.weak_points.map((w) => el("li", { class: "weak" },
    el("p", { class: "weak-text", text: w.text }),
    el("div", { class: "issue-tags" }, ...w.issues.map((i) => el("span", { class: "issue-tag", text: t(`iss_${i}`) })))))
    : [el("li", { class: "empty-ok", text: t("no_weak") })]));
}

// ------------------------------------------------------------------ optimize + translate
async function runOptimize() {
  const resume = $("#resume-text").value.trim();
  if (resume.length < 30) { showError(t("need_resume")); return; }
  try {
    const data = await withBusy(t("optimizing"), () => api("/api/optimize", {
      resume_text: resume, job_description: $("#jd-text").value.trim(), language: state.analysis?.language ?? null,
    }));
    state.optimized = data.optimized_text;
    state.lastOptimize = data;
    $("#opt-text").value = data.optimized_text;
    $("#opt-result").hidden = false;
    renderChanges(data);
    await rescore(false);
    $("#opt-text").focus();
  } catch (err) {
    toast(err.message);
  }
}

function renderChanges(data) {
  const engine = $("#opt-engine");
  engine.hidden = false;
  engine.className = `badge ${data.engine === "ai" ? "badge-ok" : "badge-warn"}`;
  engine.textContent = data.engine === "ai" ? t("opt_engine_ai", { model: data.model }) : t("opt_engine_rules");
  $("#changes").replaceChildren(...data.changes.map((c) => {
    const item = el("li", { class: "change" }, el("span", { class: "change-type", text: t(`ch_${c.type}`) }));
    if (c.type === "bullet") {
      item.append(el("del", { text: c.before }), el("ins", { text: c.after }));
    } else if (c.type === "summary_added") {
      item.append(el("ins", { text: c.after }));
    } else if (c.items) {
      item.append(c.type === "keywords_added"
        ? el("ul", { class: "chips" }, ...c.items.map((k) => el("li", { class: "chip chip-ok", text: k })))
        : el("ul", {}, ...c.items.map((k) => el("li", { text: k }))));
    }
    return item;
  }));
}

async function rescore(announce = true) {
  const text = $("#opt-text").value.trim();
  if (text.length < 30) return;
  state.optimized = text;
  const data = await api("/api/analyze", { resume_text: text, job_description: $("#jd-text").value.trim() });
  const box = $("#opt-score");
  box.hidden = false;
  box.textContent = t("opt_score", { old: state.originalScore, new: data.score });
  if (announce) toast(box.textContent);
}

async function runTranslate() {
  const text = ($("#opt-text").value || $("#resume-text").value).trim();
  const target = $("#translate-lang").value;
  try {
    const data = await withBusy(t("translating"), () => api("/api/translate", { text, target_language: target }));
    $("#opt-text").value = data.translated_text;
    state.optimized = data.translated_text;
    $("#opt-result").hidden = false;
    toast(t("translated"));
  } catch (err) {
    toast(err.message);
  }
}

// ------------------------------------------------------------------ cover letters
async function runLetters() {
  const resume = (state.optimized || $("#resume-text").value).trim();
  if (resume.length < 30) { showError(t("need_resume")); return; }
  try {
    const data = await withBusy(t("cl_generating"), () => api("/api/cover-letters", {
      resume_text: resume, job_description: $("#jd-text").value.trim(),
      language: state.analysis?.language ?? null,
      company: $("#cl-company").value.trim(), role: $("#cl-role").value.trim(),
    }));
    state.letters = data;
    $("#cl-result").hidden = false;
    renderLetterEngine();
    showLetter(document.querySelector("input[name=tone]:checked").value);
    $("#cl-text").focus();
  } catch (err) {
    toast(err.message);
  }
}

function renderLetterEngine() {
  const p = $("#cl-engine");
  p.hidden = false;
  p.textContent = state.letters.engine === "ai" ? t("cl_engine_ai", { model: state.letters.model }) : t("cl_engine_rules");
}

function showLetter(tone) {
  if (state.letters && TONES.includes(tone)) $("#cl-text").value = state.letters.letters[tone];
}

function downloadBlob(blob, name) {
  const url = URL.createObjectURL(blob);
  const a = el("a", { href: url, download: name });
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

// ------------------------------------------------------------------ export
function exportText() {
  const src = document.querySelector("input[name=ex-source]:checked").value;
  return ((src === "optimized" && ($("#opt-text").value || state.optimized)) || $("#resume-text").value).trim();
}

function exportOptions() {
  return {
    template: state.template,
    accent: state.accent || null,
    bold_keywords: $("#ex-bold").checked,
    job_description: $("#jd-text").value.trim(),
  };
}

/** Template cards: a mini wireframe of the layout + ATS badge. */
function renderTemplates() {
  const list = $("#template-list");
  if (!state.templates.length) return;
  list.replaceChildren(...state.templates.map((tpl) => {
    const accentHex = state.accents[state.accent || tpl.accent] || "#2563eb";
    const thumb = el("span", { class: `tpl-thumb th-${tpl.layout} th-${tpl.header}`, "aria-hidden": "true" },
      el("span", { class: "th-head" }), el("span", { class: "th-lines" }), el("span", { class: "th-side" }));
    thumb.style.setProperty("--tpl-accent", accentHex);
    const input = el("input", { type: "radio", name: "template", value: tpl.id });
    input.checked = tpl.id === state.template;
    const badge = el("span", { class: `tpl-badge ${tpl.ats ? "ats" : "design"}`, text: t(tpl.ats ? "ex_ats_safe" : "ex_two_col") });
    return el("label", { class: "tpl-option" }, input,
      el("span", { class: "tpl-card" }, thumb, el("span", { class: "tpl-name", text: t(`tpl_${tpl.id}`) }), badge));
  }));
  renderTemplateNote();
}

function renderTemplateNote() {
  const tpl = state.templates.find((x) => x.id === state.template);
  $("#tpl-note").textContent = tpl && !tpl.ats ? t("ex_two_col_note") : "";
}

/** Accent swatches: "template default" + palette (radio group, keyboard accessible). */
function renderAccents() {
  const list = $("#accent-list");
  const options = [["", null], ...Object.entries(state.accents)];
  list.replaceChildren(...options.map(([name, hex]) => {
    const input = el("input", { type: "radio", name: "accent", value: name, "aria-label": name ? t(`acc_${name}`) : t("ex_accent_default") });
    input.checked = name === (state.accent || "");
    const swatch = el("span", { class: `swatch${name ? "" : " swatch-default"}`, title: name ? t(`acc_${name}`) : t("ex_accent_default") });
    if (hex) swatch.style.setProperty("--sw", hex);
    return el("label", { class: "accent-option" }, input, swatch);
  }));
}

let previewTimer;
let previewSeq = 0;
function schedulePreview() {
  clearTimeout(previewTimer);
  previewTimer = setTimeout(renderPreview, 300);
}

/** Fit the A4 iframe (794px wide) into the preview column. */
function fitPreview() {
  const frame = $("#preview");
  const box = $("#preview-frame");
  const scale = Math.min(1, (box.clientWidth - 24) / 794);
  const doc = frame.contentDocument;
  const height = doc?.documentElement ? doc.documentElement.scrollHeight : 1123;
  frame.style.height = `${height}px`;
  const wrap = $("#preview-scale");
  wrap.style.transform = `scale(${scale})`;
  wrap.style.height = `${height * scale}px`;
}

async function renderPreview() {
  const text = exportText();
  const frame = $("#preview");
  if (text.length < 30) { frame.srcdoc = ""; return; }
  const seq = ++previewSeq;
  try {
    const data = await api("/api/preview", { resume_text: text, ...exportOptions() });
    if (seq !== previewSeq) return; // a newer preview request superseded this one
    frame.onload = fitPreview;
    frame.srcdoc = data.html;
  } catch { /* preview is best-effort */ }
}

async function runExport() {
  const text = exportText();
  if (text.length < 30) { toast(t("need_resume")); return; }
  const format = document.querySelector("input[name=ex-format]:checked").value;
  try {
    const res = await withBusy(t("exporting"), () => api("/api/export",
      { resume_text: text, format, ...exportOptions() }, { raw: true }));
    const disposition = res.headers.get("Content-Disposition") || "";
    const name = (disposition.match(/filename="([^"]+)"/) || [])[1] || `resume.${format}`;
    downloadBlob(await res.blob(), name);
    toast(t("exported"));
  } catch (err) {
    toast(err.message);
  }
}

// ------------------------------------------------------------------ tabs
const TAB_IDS = ["analysis", "optimize", "letters", "export"];
function selectTab(id, focusPanel = false) {
  TAB_IDS.forEach((tab) => {
    const btn = $(`#tab-${tab}`);
    const active = tab === id;
    btn.setAttribute("aria-selected", String(active));
    btn.tabIndex = active ? 0 : -1;
    $(`#panel-${tab}`).hidden = !active;
  });
  if (id === "export") renderPreview();
  if (focusPanel) $(`#panel-${id}`).focus({ preventScroll: true });
}

function setupTabs() {
  TAB_IDS.forEach((id, idx) => {
    const btn = $(`#tab-${id}`);
    btn.addEventListener("click", () => selectTab(id));
    btn.addEventListener("keydown", (e) => {
      const rtl = document.documentElement.dir === "rtl";
      const keys = { ArrowRight: rtl ? -1 : 1, ArrowLeft: rtl ? 1 : -1 };
      let next = null;
      if (e.key in keys) next = (idx + keys[e.key] + TAB_IDS.length) % TAB_IDS.length;
      if (e.key === "Home") next = 0;
      if (e.key === "End") next = TAB_IDS.length - 1;
      if (next !== null) {
        e.preventDefault();
        selectTab(TAB_IDS[next]);
        $(`#tab-${TAB_IDS[next]}`).focus();
      }
    });
  });
  $$("[data-goto]").forEach((b) => b.addEventListener("click", () => {
    selectTab(b.dataset.goto);
    $(`#tab-${b.dataset.goto}`).focus();
  }));
}

// ------------------------------------------------------------------ init
async function init() {
  const savedTheme = localStorage.getItem("rl-theme");
  applyTheme(savedTheme || (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"));
  const savedLang = localStorage.getItem("rl-ui-lang") || (navigator.language || "en").slice(0, 2);

  $("#translate-lang").replaceChildren(...Object.entries(LANG_NAMES).map(([code, name]) => el("option", { value: code, text: name })));
  try {
    const data = await api("/api/templates");
    state.templates = data.templates;
    state.accents = data.accents;
  } catch { state.templates = []; }
  applyLanguage(savedLang);
  refreshAI();
  setInterval(refreshAI, 60_000);

  $("#ui-lang").addEventListener("change", (e) => applyLanguage(e.target.value));
  $("#theme-toggle").addEventListener("click", () => applyTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark"));
  $("#upload-btn").addEventListener("click", () => $("#file-input").click());
  $("#file-input").addEventListener("change", (e) => { handleFile(e.target.files[0]); e.target.value = ""; });
  setupDropZone();
  $("#resume-text").addEventListener("input", (e) => {
    if (!e.target.value.trim()) { state.fileMeta = null; $("#file-name").textContent = ""; }
  });
  $("#sample-btn").addEventListener("click", async () => {
    try {
      const data = await api("/api/sample");
      $("#resume-text").value = data.resume_text;
      $("#jd-text").value = data.job_description;
      state.fileMeta = null;
      $("#file-name").textContent = "";
      toast(t("sample_loaded"));
      runAnalysis();
    } catch (err) { showError(err.message); }
  });
  $("#clear-btn").addEventListener("click", () => {
    $("#resume-text").value = "";
    $("#jd-text").value = "";
    state.fileMeta = null;
    $("#file-name").textContent = "";
    $("#workspace").hidden = true;
    showError("");
    $("#resume-text").focus();
  });
  $("#analyze-btn").addEventListener("click", runAnalysis);
  setupTabs();

  $("#optimize-btn").addEventListener("click", runOptimize);
  $("#rescore-btn").addEventListener("click", () => rescore(true).catch((e) => toast(e.message)));
  $("#use-opt-btn").addEventListener("click", () => {
    $("#resume-text").value = $("#opt-text").value;
    state.fileMeta = null;
    toast(t("opt_used"));
  });
  $("#translate-btn").addEventListener("click", runTranslate);
  $("#opt-text").addEventListener("input", (e) => { state.optimized = e.target.value; });

  $("#cl-btn").addEventListener("click", runLetters);
  $$("input[name=tone]").forEach((r) => r.addEventListener("change", (e) => showLetter(e.target.value)));
  $("#cl-text").addEventListener("input", (e) => {
    const tone = document.querySelector("input[name=tone]:checked").value;
    if (state.letters) state.letters.letters[tone] = e.target.value;
  });
  $("#cl-download").addEventListener("click", () => {
    const tone = document.querySelector("input[name=tone]:checked").value;
    downloadBlob(new Blob([$("#cl-text").value], { type: "text/plain;charset=utf-8" }), `cover_letter_${tone}.txt`);
  });

  $$("[data-copy]").forEach((b) => b.addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText($(`#${b.dataset.copy}`).value);
      toast(t("copied"));
    } catch {
      $(`#${b.dataset.copy}`).select();
    }
  }));

  $("#template-list").addEventListener("change", (e) => {
    if (e.target.name === "template") { state.template = e.target.value; renderTemplateNote(); schedulePreview(); }
  });
  $("#accent-list").addEventListener("change", (e) => {
    if (e.target.name === "accent") { state.accent = e.target.value; renderTemplates(); schedulePreview(); }
  });
  $("#ex-bold").addEventListener("change", schedulePreview);
  window.addEventListener("resize", () => { if (!$("#panel-export").hidden) fitPreview(); });
  $$("input[name=ex-source]").forEach((r) => r.addEventListener("change", schedulePreview));
  $("#export-btn").addEventListener("click", runExport);
}

init();
